.layout {
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
}
@media (min-width: 768px) {
  .layout { grid-template-columns: repeat(2, 1fr); }
}
@media (min-width: 1024px) {
  .layout { grid-template-columns: repeat(3, 1fr); }
}
